+function cleanupManagedClaudePromptForTerminal(paths: ManagedHostRunPaths): void {
+  const { text: specText, value: spec } = readManagedHostRunSpec(paths);
+  if (spec.profile !== 'managed_reviewer' || spec.host !== 'claude') return;
